void insertion(std::vector<int>&a){for(std::size_t i=1;i<a.size();++i){int x=a[i];auto j=i;while(j>0&&x<a[j-1]){a[j]=a[j-1];--j;}a[j]=x;}}
bool contract(const std::vector<int>&source,const std::vector<int>&result){return std::is_sorted(result.begin(),result.end())&&std::is_permutation(source.begin(),source.end(),result.begin(),result.end());}
int main(){int n;if(!(std::cin>>n)||n<0||n>128){std::cout<<"invalid\n";return 0;}
