#include "domain.hpp"
#include <map>
#include <sstream>
std::string make_report(const std::vector<Record>&records){
 std::ostringstream out;out<<"records "<<records.size()<<'\n';
 for(const Record&r:index_id(records))out<<"id "<<r.id<<' '<<r.word<<' '<<r.value<<'\n';
 for(const Record&r:index_value(records))out<<"value "<<r.id<<' '<<r.value<<'\n';
 long long sum=0;std::map<std::string,int>words;for(const Record&r:records){sum+=r.value;++words[r.word];}
 out<<"sum "<<sum<<'\n';for(const auto&entry:words)out<<"word "<<entry.first<<' '<<entry.second<<'\n';return out.str();
}

